package io.github.diodeme.ji.ai;

import java.util.Arrays;
import java.util.Objects;
import java.util.function.Function;

/** Short-lived secret value whose string representation is always masked. */
public final class SensitiveValue implements AutoCloseable {
    private char[] value;

    private SensitiveValue(char[] value) {
        this.value = value;
    }

    public static SensitiveValue of(char[] value) {
        Objects.requireNonNull(value, "value");
        return new SensitiveValue(value.clone());
    }

    public static SensitiveValue of(String value) {
        Objects.requireNonNull(value, "value");
        return new SensitiveValue(value.toCharArray());
    }

    public synchronized <T> T use(Function<char[], T> operation) {
        Objects.requireNonNull(operation, "operation");
        ensureOpen();
        char[] copy = value.clone();
        try {
            return operation.apply(copy);
        } finally {
            Arrays.fill(copy, '\0');
        }
    }

    public synchronized boolean isEmpty() {
        ensureOpen();
        return value.length == 0;
    }

    @Override
    public synchronized void close() {
        if (value == null) return;
        Arrays.fill(value, '\0');
        value = null;
    }

    @Override
    public String toString() {
        return "[REDACTED]";
    }

    private void ensureOpen() {
        if (value == null) throw new IllegalStateException("sensitive value is closed");
    }
}
